    elements=reg['elements'];text=[x for x in recipe['elements'] if x['kind']=='text'];kind='concept icon chain' if n==1 else 'many-to-one flow' if n==2 else 'comparison table' if n==3 else 'ordered action table' if n==4 else 'verification table'
