    e.update({'blueprint_reconstruction_plan':plan,'visual_element_inventory':inventory,'visual_element_registry':inventory,'blueprint_measurement_table':{k:reg[k] for k in ['blueprint_canvas_px','ppt_canvas_in','scale_x','scale_y']},'expected_pictures':3 if n==1 else 0,'image_assets':[{'id':x['element_id'],'source':f"design/icons/tabler-outline/{x['icon']}.svg",'region':x.get('draw_bbox_px',x['blueprint_bbox_px']),'reason':'Original library chosen concept icon; small non-text SVG only','editable_information_sacrificed':False} for x in recipe['elements'] if x['kind']=='icon'],'qa_expectations':{'dual_gate_required':True,'visual_semantics_required':True,'all_key_text_editable':True,'visual_qa_required':True,'spatial_registration_required':True,'label_collision_check_required':True,'container_overflow_check_required':True,'continuous_text_flow_check_required':True,'table_semantic_typography_required':n>=3,'table_density_check_required':n>=3},'text_objects':[{'id':x['element_id'],'role':x.get('role','T7'),'font_size_pt':x['font_size_pt'],'editable':True,'text':x['text']} for x in text],'native_components':[{'id':x['element_id'],'type':x['kind'],'reason':'Native information or simple geometry; not a full-page bitmap'} for x in recipe['elements'] if x['kind']!='icon']})
