    for key,fn in [('slide_content_lock','content-lock'),('blueprint_component_signature','signature')]:e[key].update({'path':f'design/slide-{tag}-{fn}.json','sha256':sha(P/f'design/slide-{tag}-{fn}.json'),'locked':True})
